Utilities for generating random numbers.

Example of generating a random integer with fixed seed number:

```ts
import { randomIntegerBetween } from "@ende/random";
import { randomSeeded } from "@ende/random";
import { assertEquals } from "@ende/assert";

const prng = randomSeeded(1n);

assertEquals(randomIntegerBetween(1, 10, { prng }), 3);
```

Example of generating a random integer between two values:

```ts no-assert
import { randomIntegerBetween } from "@ende/random";
import { randomSeeded } from "@ende/random";

const prng = randomSeeded(BigInt(crypto.getRandomValues(new Uint32Array(1))[0]!));

const randomInteger = randomIntegerBetween(1, 10, { prng });
```

tags.doc:
Usage
```ts
import { getRandomValuesSeeded } from "@ende/random";
import { assertEquals } from "@ende/assert";

const getRandomValues = getRandomValuesSeeded(1n);
assertEquals(getRandomValues(new Uint8Array(5)), new Uint8Array([230, 11, 167, 51, 238]));
```

With a seeded value generator
```ts
import { nextFloat64, getRandomValuesSeeded } from "@ende/random";
import { assertEquals } from "@ende/assert";

const getRandomValues = getRandomValuesSeeded(1n);
assertEquals(nextFloat64(getRandomValues), 0.49116444173310125);
assertEquals(nextFloat64(getRandomValues), 0.06903754193160427);
assertEquals(nextFloat64(getRandomValues), 0.16063206851777034);
```

With an arbitrary value generator
```ts
import { nextFloat64 } from "@ende/random";
import { assertLess, assertGreaterOrEqual } from "@ende/assert";

const val = nextFloat64(crypto.getRandomValues.bind(crypto)); // example: 0.8928746327842533
assertGreaterOrEqual(val, 0);
assertLess(val, 1);
```

Basic usage
```ts
import { sample } from "@ende/random/sample";
import { assertArrayIncludes } from "@ende/assert";

const numbers = [1, 2, 3, 4];
const sampled = sample(numbers);

assertArrayIncludes(numbers, [sampled]);
```

Using `weights` option
```ts no-assert
import { sample } from "@ende/random/sample";

const values = ["a", "b", "c"];
const weights = [5, 3, 2];
const result = sample(values, { weights });
// gives "a" 50% of the time, "b" 30% of the time, and "c" 20% of the time
```

Usage
```ts
import { randomSeeded } from "@ende/random";
import { assertEquals } from "@ende/assert";

const prng = randomSeeded(1n);

assertEquals(prng(), 0.20176767697557807);
assertEquals(prng(), 0.4911644416861236);
assertEquals(prng(), 0.7924694607499987);
```

